/* Fruit Book: the coloring page on the home page.
   A tap fills the area inside the lines, like the app's fill tool, and the
   colour slips 2 px under the outline. The line art is in this file so the
   page also works when opened straight from a folder. */
(function () {
  "use strict";
  var LINES = {
"apple": "data:image/png;base64,",
"strawberry": "data:image/png;base64,",
"banana": "data:image/png;base64,",
"cherry": "data:image/png;base64,",
"pear": "data:image/png;base64,",
"grapes": "data:image/png;base64,",
"watermelon": "data:image/png;base64,"
};
  var ORDER = ["apple", "strawberry", "banana", "cherry", "pear", "grapes", "watermelon"];
  var PREFILL = {"apple": [[578, 222, "#2CBC44"], [323, 198, "#8B4513"]]};

  var demo = document.querySelector(".demo");
  if (!demo || !window.Uint8Array || !window.Promise) return;
  var canvas = demo.querySelector("canvas");
  var lines = demo.querySelector(".lines");
  var nameEl = demo.querySelector(".fruit");
  var names = JSON.parse(demo.getAttribute("data-names"));
  var pattern = canvas.getAttribute("data-label");
  var ctx = canvas.getContext("2d");
  var pencils = demo.querySelectorAll(".pencil");
  var picked = demo.querySelector('.pencil[aria-pressed="true"]');
  var color = picked ? picked.getAttribute("data-color") : "#FF0000";
  var index = 0, ticket = 0, W = 0, H = 0, walls = null, mask = null, stack = null;
  var images = {}, wallCache = {};

  function image(id) {
    if (!images[id]) images[id] = new Promise(function (resolve, reject) {
      var im = new Image();
      im.onload = function () { resolve(im); };
      im.onerror = reject;
      im.src = LINES[id];
    });
    return images[id];
  }

  function wallsFor(id, im) {
    if (wallCache[id]) return wallCache[id];
    var off = document.createElement("canvas");
    off.width = W; off.height = H;
    var o = off.getContext("2d");
    o.drawImage(im, 0, 0);
    var a = o.getImageData(0, 0, W, H).data, w = new Uint8Array(W * H);
    for (var p = 0, q = 3; p < w.length; p++, q += 4) w[p] = a[q] > 105 ? 1 : 0;
    return (wallCache[id] = w);
  }

  function show(i) {
    var id = ORDER[i], t = ++ticket;
    return image(id).then(function (im) {
      if (t !== ticket) return;
      W = im.naturalWidth; H = im.naturalHeight;
      walls = wallsFor(id, im);
      if (!mask || mask.length !== W * H) { mask = new Uint8Array(W * H); stack = new Int32Array(W * H); }
      canvas.width = W; canvas.height = H;
      lines.src = LINES[id];
      nameEl.textContent = names[id];
      canvas.setAttribute("aria-label", pattern.replace("%@", names[id]));
      clear();
      image(ORDER[(i + 1) % ORDER.length]);
    });
  }

  function clear() {
    ctx.fillStyle = "#FFFFFF";
    ctx.fillRect(0, 0, W, H);
    (PREFILL[ORDER[index]] || []).forEach(function (p) { fill(p[0], p[1], p[2]); });
  }

  function fill(x, y, hex) {
    var n = W * H, start = -1, r, dx, dy, px, py, p, sp = 0, it;
    x = Math.floor(x); y = Math.floor(y);
    // A tap on a line counts for the nearest spot inside the lines.
    for (r = 0; r <= 18 && start < 0; r++) {
      for (dy = -r; dy <= r && start < 0; dy++) {
        for (dx = -r; dx <= r; dx++) {
          if (Math.abs(dx) !== r && Math.abs(dy) !== r) continue;
          px = x + dx; py = y + dy;
          if (px < 0 || py < 0 || px >= W || py >= H) continue;
          if (!walls[py * W + px]) { start = py * W + px; break; }
        }
      }
    }
    if (start < 0) return;
    mask.fill(0);
    mask[start] = 1; stack[sp++] = start;
    while (sp) {
      p = stack[--sp]; px = p % W;
      if (px > 0 && !mask[p - 1] && !walls[p - 1]) { mask[p - 1] = 1; stack[sp++] = p - 1; }
      if (px < W - 1 && !mask[p + 1] && !walls[p + 1]) { mask[p + 1] = 1; stack[sp++] = p + 1; }
      if (p >= W && !mask[p - W] && !walls[p - W]) { mask[p - W] = 1; stack[sp++] = p - W; }
      if (p < n - W && !mask[p + W] && !walls[p + W]) { mask[p + W] = 1; stack[sp++] = p + W; }
    }
    // Grow the area 2 px into the lines so no white shows along their soft edges.
    for (it = 2; it < 4; it++) {
      for (p = 0; p < n; p++) {
        if (mask[p] || !walls[p]) continue;
        px = p % W;
        if ((px > 0 && mask[p - 1] && mask[p - 1] < it) || (px < W - 1 && mask[p + 1] && mask[p + 1] < it) ||
            (p >= W && mask[p - W] && mask[p - W] < it) || (p < n - W && mask[p + W] && mask[p + W] < it)) mask[p] = it;
      }
    }
    var rr = parseInt(hex.substr(1, 2), 16), gg = parseInt(hex.substr(3, 2), 16), bb = parseInt(hex.substr(5, 2), 16);
    var img = ctx.getImageData(0, 0, W, H), d = img.data;
    for (p = 0; p < n; p++) {
      if (mask[p]) { var q = p * 4; d[q] = rr; d[q + 1] = gg; d[q + 2] = bb; d[q + 3] = 255; }
    }
    ctx.putImageData(img, 0, 0);
  }

  canvas.addEventListener("click", function (e) {
    if (!walls) return;
    var r = canvas.getBoundingClientRect();
    fill((e.clientX - r.left) * W / r.width, (e.clientY - r.top) * H / r.height, color);
  });
  Array.prototype.forEach.call(pencils, function (b) {
    b.addEventListener("click", function () {
      Array.prototype.forEach.call(pencils, function (o) { o.setAttribute("aria-pressed", o === b ? "true" : "false"); });
      color = b.getAttribute("data-color");
    });
  });
  demo.querySelector('[data-act="next"]').addEventListener("click", function () {
    index = (index + 1) % ORDER.length;
    show(index).catch(still);
  });
  demo.querySelector('[data-act="clear"]').addEventListener("click", function () { if (walls) clear(); });

  function still() { demo.className += " still"; }
  show(0).catch(still);
})();
